/* Interactive portfolio. Renders entirely from data/profile.json (generated by
   profile/scripts/build.py from the GitHub API) — nothing here is hand-maintained. */
"use strict";
(() => {
  const SVGNS = "http://www.w3.org/2000/svg";
  const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const one = (k) => document.querySelector(`[data-bind="${k}"]`);
  const all = (k) => document.querySelectorAll(`[data-bind="${k}"]`);
  const safeUrl = (u) => (/^(https?:|mailto:|#)/i.test(u || "") ? u : "#");

  // Element builder. Text is always inserted as text nodes — repository data never becomes markup.
  function el(tag, attrs = {}, ...kids) {
    const svg = tag.startsWith("svg:");
    const n = svg ? document.createElementNS(SVGNS, tag.slice(4)) : document.createElement(tag);
    for (const [k, v] of Object.entries(attrs)) {
      if (v == null || v === false) continue;
      if (k.startsWith("on")) n.addEventListener(k.slice(2), v);
      else if (k === "href") n.setAttribute("href", safeUrl(v));
      else n.setAttribute(k, v === true ? "" : v);
    }
    for (const c of kids.flat()) if (c != null && c !== false) n.append(c.nodeType ? c : String(c));
    return n;
  }

  const ICONS = {
    star: '<path d="M8 1.6l1.9 4 4.3.5-3.2 3 .9 4.3L8 11.3l-3.9 2.1.9-4.3-3.2-3 4.3-.5z"/>',
    fork: '<circle cx="4" cy="3" r="1.6"/><circle cx="12" cy="3" r="1.6"/><circle cx="8" cy="13" r="1.6"/><path d="M4 4.6v1.2a2 2 0 002 2h4a2 2 0 002-2V4.6M8 7.8v3.6"/>',
    commit: '<circle cx="8" cy="8" r="2.6"/><path d="M1 8h4.4M10.6 8H15"/>',
    clock: '<circle cx="8" cy="8" r="6.2"/><path d="M8 4.6V8l2.4 1.6"/>',
    law: '<path d="M8 2v12M4.5 14h7M2.5 4.5h11M3.8 4.5L2.2 8.4h3.2zM12.2 4.5l-1.6 3.9h3.2z"/>',
    pin: '<path d="M8 14.5s5-4.6 5-8.3a5 5 0 00-10 0c0 3.7 5 8.3 5 8.3z"/><circle cx="8" cy="6.2" r="1.8"/>',
    calendar: '<rect x="2" y="3" width="12" height="11" rx="2"/><path d="M2 6.5h12M5.5 1.5v3M10.5 1.5v3"/>',
    repo: '<path d="M3 2.5h8.5a1 1 0 011 1V12H4.2A1.2 1.2 0 003 13.2V2.5zM3 13.2a1.2 1.2 0 001.2 1.3h8.3"/>',
    chevron: '<path d="M4 6l4 4 4-4"/>',
  };
  function icon(name) {
    const s = document.createElementNS(SVGNS, "svg");
    for (const [k, v] of Object.entries({ viewBox: "0 0 16 16", fill: "none", stroke: "currentColor", "stroke-width": "1.4",
      "stroke-linecap": "round", "stroke-linejoin": "round", "aria-hidden": "true" })) s.setAttribute(k, v);
    s.innerHTML = ICONS[name]; // static, trusted markup
    return s;
  }

  const fmtDate = (iso) => new Date(iso.length === 10 ? iso + "T00:00:00Z" : iso)
    .toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric", timeZone: "UTC" });
  const fmtNum = (n) => (n >= 10000 ? (n / 1000).toFixed(1).replace(/\.0$/, "") + "k" : n.toLocaleString("en-US"));
  const plural = (n, w, p = w + "s") => `${fmtNum(n)} ${n === 1 ? w : p}`;
  const slug = (s) => s.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
  const clip = (s, n) => (s && s.length > n ? s.slice(0, n).replace(/\s+\S*$/, "") + "…" : s || "");

  // ── Tooltip ──────────────────────────────────────────────────────────────
  const tip = document.getElementById("tip");
  function placeTip(x, y) {
    const r = tip.getBoundingClientRect();
    let left = x + 14, top = y + 16;
    if (left + r.width > innerWidth - 8) left = x - r.width - 14;
    if (top + r.height > innerHeight - 8) top = y - r.height - 14;
    tip.style.left = Math.max(8, left) + "px";
    tip.style.top = Math.max(8, top) + "px";
  }
  function attachTip(node, build) {
    node._tip = build;
    const show = (x, y) => { tip.replaceChildren(...build()); tip.classList.add("show"); placeTip(x, y); };
    node.addEventListener("pointerenter", (e) => show(e.clientX, e.clientY));
    node.addEventListener("pointermove", (e) => placeTip(e.clientX, e.clientY));
    node.addEventListener("pointerleave", () => tip.classList.remove("show"));
    node.addEventListener("focus", () => { const r = node.getBoundingClientRect(); show(r.left + r.width / 2, r.bottom); });
    node.addEventListener("blur", () => tip.classList.remove("show"));
  }
  // Touch has no hover, so a tap must not jump straight away: first tap previews, second commits.
  let armed = null;
  function intent(node, preview, commit) {
    node.addEventListener("pointerup", (e) => {
      if (e.pointerType !== "touch") return;
      e.preventDefault();
      if (armed === node) { armed = null; tip.classList.remove("show"); commit(); return; }
      armed = node;
      preview();
      tip.replaceChildren(...node._tip());
      tip.classList.add("show");
      placeTip(e.clientX, e.clientY);
    });
    node.addEventListener("click", (e) => { if (!e.pointerType || e.pointerType !== "touch") commit(); });
    node.addEventListener("keydown", (e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); commit(); } });
  }
  document.addEventListener("pointerdown", (e) => {
    if (armed && !armed.contains(e.target)) {
      const prev = armed;
      armed = null;
      tip.classList.remove("show");
      prev.dispatchEvent(new Event("pointerleave"));
    }
  });
  const tipBody = (title, ...lines) => [el("strong", {}, title), ...lines.filter(Boolean).map((l) => el("div", { class: "sub" }, l))];

  // ── Reveal + count-up on scroll ──────────────────────────────────────────
  const io = new IntersectionObserver((entries) => {
    for (const e of entries) {
      if (!e.isIntersecting) continue;
      e.target.classList.add("in");
      e.target.querySelectorAll("[data-count]").forEach(countUp);
      io.unobserve(e.target);
    }
  }, { threshold: 0.12, rootMargin: "0px 0px -40px 0px" });

  function countUp(node) {
    const target = Number(node.dataset.count), suffix = node.dataset.suffix || "";
    if (reduce || target === 0) { node.textContent = fmtNum(target) + suffix; return; }
    const start = performance.now(), dur = 1300;
    const step = (t) => {
      const p = Math.min(1, (t - start) / dur), eased = 1 - Math.pow(1 - p, 3);
      node.textContent = fmtNum(Math.round(target * eased)) + suffix;
      if (p < 1) requestAnimationFrame(step);
    };
    requestAnimationFrame(step);
  }

  // ── State shared by the explorer and the elements that filter it ─────────
  const state = { q: "", cat: "All", sort: "updated", filter: null };
  let M, repos, byName;

  fetch("data/profile.json", { cache: "no-cache" })
    .then((r) => { if (!r.ok) throw new Error("HTTP " + r.status); return r.json(); })
    .then((m) => { M = m; render(); })
    .catch((err) => {
      console.error(err);
      document.documentElement.classList.remove("js");
      one("status").textContent = "Live data is temporarily unavailable — the full profile is on GitHub.";
    });

  function render() {
    repos = M.repos.filter((p) => !p.fork);
    byName = Object.fromEntries(repos.map((p) => [p.name, p]));
    const gh = `https://github.com/${M.login}`;
    all("github-link").forEach((a) => a.setAttribute("href", gh));
    one("source-link").setAttribute("href", `${gh}/${M.login}/blob/main/profile/ARCHITECTURE.md`);
    one("brand").replaceChildren(M.identity.name.replace(/\.$/, ""), el("span", {}, "."));
    document.title = `${M.identity.name} — ${M.identity.roles[0] || "Engineering"} Portfolio`;

    hero(gh);
    metrics();
    one("overview").textContent = M.identity.overview;
    focus();
    tech();
    featured();
    explorer();
    activity();
    openSource();
    connect(gh);
    one("footer").textContent = `Synced from the GitHub API by GitHub Actions · latest activity ${M.latest_activity ? fmtDate(M.latest_activity) : "—"}`;
    nav();
    document.querySelectorAll(".reveal, .bars, .heat, .timeline, .spark").forEach((n) => io.observe(n));
  }

  // ── Hero ─────────────────────────────────────────────────────────────────
  function hero(gh) {
    const id = M.identity;
    one("status").textContent = `Live from GitHub · latest activity ${M.latest_activity ? fmtDate(M.latest_activity) : "—"}`;
    one("name").textContent = id.name;
    one("headline").textContent = id.headline;
    roles(id.roles);
    one("meta").replaceChildren(
      id.location && el("span", {}, icon("pin"), id.location),
      el("span", {}, icon("repo"), plural(M.totals.public_repos, "public repository", "public repositories")),
      M.user && M.user.created && el("span", {}, icon("calendar"), `On GitHub since ${new Date(M.user.created).getUTCFullYear()}`));
    graph();
  }

  function roles(list) {
    const box = one("roles");
    box.setAttribute("aria-label", list.join(", "));
    box.removeAttribute("aria-live");
    let widest = 0;
    for (const r of list) { const s = el("span", {}, r); box.append(s); widest = Math.max(widest, s.offsetWidth); s.remove(); }
    box.style.width = widest + 4 + "px";
    let i = 0, cur = el("span", { "aria-hidden": "true" }, list[0]);
    box.append(cur);
    if (reduce || list.length < 2) return;
    // One full cycle, then settle on the primary role — motion that informs, then rests (WCAG 2.2.2).
    let paused = false, steps = 0;
    const line = box.closest(".role-line");
    line.addEventListener("pointerenter", () => (paused = true));
    line.addEventListener("pointerleave", () => (paused = false));
    const timer = setInterval(() => {
      if (paused || document.hidden) return;
      i = (i + 1) % list.length;
      const nxt = el("span", { class: "next", "aria-hidden": "true" }, list[i]);
      box.append(nxt);
      nxt.getBoundingClientRect();
      cur.classList.add("out");
      nxt.classList.remove("next");
      const old = cur;
      setTimeout(() => old.remove(), 800);
      cur = nxt;
      if (++steps >= list.length) clearInterval(timer);
    }, 2400);
  }

  function graph() {
    const svg = one("graph");
    const nodes = [...repos].sort((a, b) => b.score - a.score).slice(0, 18);
    if (!nodes.length) return;
    const cx = 220, cy = 205, R = 112;
    const cats = [...new Set(nodes.map((p) => p.category))];
    const hr = cats.length > 1 ? 42 : 0;
    // Outer ring: repositories, ordered by category so spokes stay short. Inner ring: practice areas.
    nodes.sort((a, b) => cats.indexOf(a.category) - cats.indexOf(b.category) || b.score - a.score);
    const at = (r, i, n, off = 0) => { const a = -Math.PI / 2 + off + (2 * Math.PI * i) / n; return { x: cx + r * Math.cos(a), y: cy + r * Math.sin(a), a }; };
    const pos = nodes.map((_, i) => at(R, i, nodes.length));
    const hubPos = cats.map((c, k) => {
      const idx = nodes.map((p, i) => (p.category === c ? i : -1)).filter((i) => i >= 0);
      const mean = Math.atan2(idx.reduce((s, i) => s + Math.sin(pos[i].a), 0), idx.reduce((s, i) => s + Math.cos(pos[i].a), 0));
      return hr ? { x: cx + hr * Math.cos(mean), y: cy + hr * Math.sin(mean) } : { x: cx, y: cy };
    });
    const layer = el("svg:g", { class: "graph-layer" });
    layer.append(el("svg:circle", { cx, cy, r: R, fill: "none", stroke: "#D3E7F7", "stroke-dasharray": "2 6" }));
    if (hr) layer.append(el("svg:circle", { cx, cy, r: hr, fill: "#F3F9FE", stroke: "#E3EAF2" }));
    const spokes = nodes.map((p, i) => {
      const h = hubPos[cats.indexOf(p.category)];
      const s = el("svg:line", { class: "g-spoke g-edge", x1: h.x, y1: h.y, x2: pos[i].x, y2: pos[i].y, pathLength: 1, style: `--d:${0.35 + 0.04 * i}s` });
      layer.append(s);
      return s;
    });
    const edges = [];
    nodes.forEach((p, i) => nodes.slice(i + 1).forEach((q, k) => {
      const j = i + 1 + k;
      const shared = p.topics.filter((t) => q.topics.includes(t)).length + p.tech.filter((t) => q.tech.includes(t)).length;
      if (!shared) return;
      const mx = cx + ((pos[i].x + pos[j].x) / 2 - cx) * 0.15, my = cy + ((pos[i].y + pos[j].y) / 2 - cy) * 0.15;
      const e = el("svg:path", {
        class: "g-edge", d: `M${pos[i].x} ${pos[i].y}Q${mx} ${my} ${pos[j].x} ${pos[j].y}`, pathLength: 1,
        "stroke-opacity": Math.min(0.25 + 0.08 * shared, 0.6).toFixed(2), "stroke-width": (1 + 0.35 * Math.min(shared, 4)).toFixed(2),
        style: `--d:${0.6 + 0.05 * edges.length}s`,
      });
      e.ends = [i, j];
      edges.push(e);
      layer.append(e);
    }));
    let groups = [];
    const light = (repoIdx, hubIdx) => {
      const on = repoIdx.length > 0;
      svg.classList.toggle("dim", on);
      groups.forEach((g, i) => g.classList.toggle("hot", repoIdx.includes(i)));
      hubs.forEach((h, k) => h.classList.toggle("hot", hubIdx.includes(k)));
      spokes.forEach((s, i) => s.classList.toggle("hot", repoIdx.includes(i) && hubIdx.includes(cats.indexOf(nodes[i].category))));
      edges.forEach((e) => e.classList.toggle("hot", on && repoIdx.length === 1 && e.ends.includes(repoIdx[0])));
    };
    const neighbours = (i) => [i, ...edges.filter((e) => e.ends.includes(i)).map((e) => e.ends[0] === i ? e.ends[1] : e.ends[0])];
    const hubs = cats.map((c, k) => {
      const members = nodes.map((p, i) => (p.category === c ? i : -1)).filter((i) => i >= 0);
      const g = el("svg:g", { class: "g-hub", tabindex: 0, role: "button", "aria-label": `${c}: ${members.length} repositories — filter explorer` },
        el("svg:circle", { cx: hubPos[k].x, cy: hubPos[k].y, r: 4.5 }));
      const on = () => light(members, [k]), off = () => light([], []);
      g.addEventListener("pointerenter", on); g.addEventListener("pointerleave", off);
      g.addEventListener("focus", on); g.addEventListener("blur", off);
      attachTip(g, () => tipBody(c, plural(members.length, "repository", "repositories"), "Select to filter the explorer"));
      const go = () => { const b = document.querySelector(`[data-cat="${CSS.escape(c)}"]`); if (b) b.click(); document.getElementById("explorer").scrollIntoView({ behavior: reduce ? "auto" : "smooth" }); };
      intent(g, on, go);
      return g;
    });
    groups = nodes.map((p, i) => {
      const { x, y, a } = pos[i];
      const rad = 5 + Math.min(7, Math.log2(1 + p.commits) * 1.1);
      const dx = Math.cos(a), dy = Math.sin(a);
      const anchor = dx > 0.3 ? "start" : dx < -0.3 ? "end" : "middle";
      const g = el("svg:g", { class: "g-node", tabindex: 0, role: "button", "aria-label": `${p.name}: ${p.tagline || p.description || p.category}`, style: `--d:${0.25 + 0.06 * i}s` },
        el("svg:circle", { class: "halo", cx: x, cy: y, r: rad + 10 }),
        el("svg:circle", { class: "dot", cx: x, cy: y, r: rad, fill: p.featured ? "#1D6FB2" : "#A9D4F2", stroke: "#fff", "stroke-width": 2.5 }),
        el("svg:text", { x: x + dx * (rad + 9), y: y + dy * (rad + 11) + 4, "text-anchor": anchor }, clip(p.name, 15)));
      const on = () => light(neighbours(i), [cats.indexOf(p.category)]), off = () => light([], []);
      g.addEventListener("pointerenter", on); g.addEventListener("pointerleave", off);
      g.addEventListener("focus", on); g.addEventListener("blur", off);
      attachTip(g, () => tipBody(p.name, p.category, clip(p.tagline || p.description, 140),
        [p.language, plural(p.commits, "commit"), plural(p.stars, "star")].filter(Boolean).join(" · ")));
      intent(g, on, () => openRepo(p.name));
      return g;
    });
    layer.append(...hubs, ...groups);
    svg.append(layer);
    // Gentle depth: the graph leans toward the pointer (mouse/pen only, never on touch or reduced motion).
    const card = svg.closest(".graph-card");
    if (!reduce) {
      card.addEventListener("pointermove", (e) => {
        if (e.pointerType === "touch") return;
        const b = card.getBoundingClientRect();
        layer.style.transform = `translate(${((e.clientX - b.left) / b.width - 0.5) * 10}px, ${((e.clientY - b.top) / b.height - 0.5) * 10}px)`;
      });
      card.addEventListener("pointerleave", () => (layer.style.transform = ""));
    }
  }

  function openRepo(name) {
    const card = document.getElementById("p-" + slug(name));
    if (card) {
      card.scrollIntoView({ behavior: reduce ? "auto" : "smooth", block: "center" });
      card.classList.remove("flash"); void card.offsetWidth; card.classList.add("flash");
      return;
    }
    setFilter({ label: name, names: [name] });
  }

  // ── Metrics ──────────────────────────────────────────────────────────────
  function metrics() {
    const t = M.totals, a = M.activity;
    const items = [
      [t.public_repos, "Public repositories"], [t.commits, "Commits across default branches"],
      [a.total, "Contributions · 12 months"], [a.active_days, "Active days · 12 months"],
      [t.languages, "Languages"], [t.technologies, "Technologies with evidence"]];
    one("metrics").replaceChildren(...items.map(([v, l]) =>
      el("div", { class: "metric" }, el("div", { class: "value", "data-count": v }, "0"), el("div", { class: "label" }, l))));
  }

  // ── Focus ────────────────────────────────────────────────────────────────
  function focus() {
    one("focus").replaceChildren(...M.focus.map((f, i) => {
      const n = f.repos.length;
      const body = [el("span", { class: "bar" }), el("h3", {}, f.title), el("p", {}, f.summary),
        el("div", { class: "evidence" }, n ? [el("i", {}, Array.from({ length: Math.min(n, 5) }, () => el("b"))),
          plural(n, "public repository", "public repositories")] : "Practice area")];
      const attrs = { class: "focus reveal", style: `--d:${0.05 * i}s` };
      if (!n) return el("div", attrs, body);
      const b = el("button", { ...attrs, type: "button", onclick: () => setFilter({ label: f.title, names: f.repos }) }, body);
      attachTip(b, () => tipBody(f.title, "Show: " + f.repos.join(", ")));
      return b;
    }));
  }

  // ── Technology ───────────────────────────────────────────────────────────
  function tech() {
    const rows = [];
    if (M.languages.length) {
      rows.push(el("div", { class: "tech-row" }, el("div", { class: "eyebrow" }, "Languages"),
        el("div", { class: "chips" }, M.languages.filter((l) => l.name !== "Other").map((l) =>
          el("span", { class: "chip" }, l.name, el("span", { class: "count" }, (l.share * 100).toFixed(0) + "%"))))));
    }
    let declared = false;
    for (const g of M.tech) {
      rows.push(el("div", { class: "tech-row" }, el("div", { class: "eyebrow" }, g.group),
        el("div", { class: "chips" }, g.items.map((t) => {
          if (t.declared) { declared = true; return el("span", { class: "chip dashed" }, t.name); }
          const b = el("button", { class: "chip", type: "button", onclick: () => setFilter({ label: t.name, names: t.repos }) },
            t.name, el("span", { class: "count" }, String(t.repos.length)));
          attachTip(b, () => tipBody(t.name, `Used in ${plural(t.repos.length, "repository", "repositories")}`, t.repos.join(", ")));
          return b;
        }))));
    }
    one("tech").replaceChildren(...rows);
    one("tech-note").textContent = (declared ? "Dashed = professional experience (configured, no public repository). " : "") +
      "Numbers = public repositories with evidence. Select a technology to filter the explorer.";
  }

  // ── Featured projects ────────────────────────────────────────────────────
  function stats(p) {
    return el("div", { class: "stats-row" },
      el("span", {}, icon("star"), plural(p.stars, "star")), el("span", {}, icon("fork"), plural(p.forks, "fork")),
      el("span", {}, icon("commit"), plural(p.commits, "commit")),
      el("span", {}, icon("clock"), "Updated " + fmtDate(p.last_commit || p.pushed)),
      p.license && el("span", {}, icon("law"), p.license === "Custom" ? "Custom license" : p.license));
  }

  function sparkline(weeks) {
    if (!weeks || weeks.filter(Boolean).length < 4) return null;
    const top = Math.max(...weeks) || 1, w = 300, h = 40, step = w / (weeks.length - 1);
    const pts = weeks.map((v, i) => [i * step, h - (v / top) * (h - 4) - 2]);
    const line = "M" + pts.map(([x, y]) => `${x.toFixed(1)} ${y.toFixed(1)}`).join(" L");
    return el("div", { class: "spark" },
      el("div", { class: "spark-label" }, el("span", {}, "Commits · last 52 weeks"), el("span", {}, plural(weeks.reduce((a, b) => a + b, 0), "commit"))),
      el("svg:svg", { viewBox: `0 0 ${w} ${h}`, preserveAspectRatio: "none", width: "100%", height: h, "aria-hidden": "true" },
        el("svg:path", { class: "area", d: `${line} L${w} ${h} L0 ${h} Z` }),
        el("svg:path", { class: "line", d: line, pathLength: 1, "vector-effect": "non-scaling-stroke" })));
  }

  function featured() {
    const names = M.featured.filter((n) => byName[n]);
    one("featured").replaceChildren(...names.map((name, i) => {
      const p = byName[name];
      const techs = [p.language, ...p.tech.filter((t) => t !== p.language)].filter(Boolean);
      const actions = [["Repository", p.url, true], ["Live demo", p.demo], ["Website", p.homepage], ["Documentation", p.docs],
        ["Architecture", p.architecture], p.release && ["Release " + p.release.tag, p.release.url]].filter((a) => a && a[1]);
      const detailId = "d-" + slug(name);
      const details = el("div", { class: "details", id: detailId }, el("div", {}, el("dl", {},
        ...[["Topics", p.topics.join(", ") || "—"], ["Open issues", p.open_issues], ["Open pull requests", p.open_prs],
          ["Watchers", p.watchers], ["Created", fmtDate(p.created)], ["Default branch", p.branch || "—"],
          ["Latest release", p.release ? `${p.release.tag} · ${fmtDate(p.release.date)}` : "—"],
          ["Capabilities source", p.feature_source === "config" ? "Curated" : "Project README"]]
          .flatMap(([k, v]) => [el("dt", {}, k), el("dd", {}, String(v))]))));
      const toggle = el("button", { class: "toggle", type: "button", "aria-expanded": "false", "aria-controls": detailId,
        onclick: () => { const open = details.classList.toggle("open"); toggle.setAttribute("aria-expanded", String(open)); toggle.firstChild.textContent = open ? "Fewer details" : "More details"; } },
        "More details", icon("chevron"));
      const card = el("article", { class: "card project reveal", id: "p-" + slug(name), style: `--d:${0.06 * (i % 2)}s` },
        el("div", { class: "project-top" }, el("span", { class: "eyebrow" }, p.category),
          el("span", { class: "pills" }, p.archived && el("span", { class: "pill" }, "Archived"),
            el("span", { class: "pill" }, p.visibility === "PRIVATE" ? "Private" : "Public"),
            p.release && el("span", { class: "pill accent" }, p.release.tag))),
        el("h3", {}, el("a", { href: p.url }, p.name)),
        el("p", { class: "desc" }, p.tagline || p.description),
        p.features.length && el("ul", { class: "features" }, p.features.slice(0, 4).map((f) =>
          el("li", {}, el("strong", {}, f.title), f.detail && el("span", {}, f.detail)))),
        techs.length && el("div", { class: "chips" }, techs.map((t) => el("span", { class: "chip ghost" }, t))),
        el("div", { class: "project-foot" }, stats(p), sparkline(p.weekly), toggle, details,
          el("div", { class: "actions" }, actions.map(([l, u, primary]) => el("a", { class: "btn small" + (primary ? " primary" : ""), href: u }, l)))));
      card.addEventListener("pointermove", (e) => {
        const b = card.getBoundingClientRect();
        card.style.setProperty("--mx", e.clientX - b.left + "px");
        card.style.setProperty("--my", e.clientY - b.top + "px");
      });
      return card;
    }));
  }

  // ── Explorer ─────────────────────────────────────────────────────────────
  const repoNodes = new Map();

  function repoCard(p) {
    const techs = p.tech.filter((t) => t !== p.language).slice(0, 3);
    return el("article", { class: "card repo", "data-key": p.name },
      el("div", { class: "top" }, el("span", { class: "eyebrow" }, p.category),
        el("span", { class: "pills" }, p.featured && el("span", { class: "pill accent" }, "Featured"),
          p.archived && el("span", { class: "pill" }, "Archived"), p.visibility === "PRIVATE" && el("span", { class: "pill" }, "Private"))),
      el("h3", {}, el("a", { href: p.url }, p.name)),
      el("p", {}, p.tagline || p.description || "No description provided."),
      techs.length && el("div", { class: "chips", style: "margin-top:12px" }, techs.map((t) => el("span", { class: "chip ghost" }, t))),
      el("div", { class: "foot" },
        p.language && el("span", {}, el("i", { class: "lang-dot" }), p.language),
        el("span", {}, icon("star"), String(p.stars)), el("span", {}, icon("commit"), String(p.commits)),
        el("span", {}, icon("clock"), fmtDate(p.last_commit || p.pushed))));
  }

  function explorer() {
    const search = one("search"), sort = one("sort");
    search.addEventListener("input", () => { state.q = search.value.trim().toLowerCase(); renderRepos(); });
    sort.addEventListener("change", () => { state.sort = sort.value; renderRepos(); });
    search.placeholder += "  ( / )";
    addEventListener("keydown", (e) => {
      if (e.key === "/" && !/^(INPUT|SELECT|TEXTAREA)$/.test(document.activeElement.tagName)) { e.preventDefault(); search.focus({ preventScroll: true }); search.scrollIntoView({ block: "center", behavior: reduce ? "auto" : "smooth" }); }
    });
    search.addEventListener("keydown", (e) => { if (e.key === "Escape") { search.value = ""; state.q = ""; renderRepos(); } });
    const cats = [["All", repos.length], ...M.categories.map((c) => [c.name, c.repos.filter((n) => byName[n]).length])];
    const row = one("categories");
    const clear = el("button", { class: "chip active-filter", type: "button", "aria-label": "Clear filter", onclick: () => setFilter(null) });
    row.replaceChildren(...cats.map(([name, n]) => el("button", { class: "chip", type: "button", "aria-pressed": String(name === "All"), "data-cat": name,
      onclick: () => { state.cat = name; row.querySelectorAll("[data-cat]").forEach((b) => b.setAttribute("aria-pressed", String(b.dataset.cat === name))); renderRepos(); } },
      name, el("span", { class: "count" }, String(n)))), clear, el("span", { class: "result-count", "aria-live": "polite" }));
    repos.forEach((p) => repoNodes.set(p.name, repoCard(p)));
    renderRepos(false);
  }

  function setFilter(f) {
    state.filter = f;
    const clear = document.querySelector(".active-filter");
    clear.classList.toggle("show", !!f);
    clear.replaceChildren(...(f ? [f.label, el("span", { class: "count", "aria-hidden": "true" }, "✕")] : []));
    renderRepos();
    if (f) document.getElementById("explorer").scrollIntoView({ behavior: reduce ? "auto" : "smooth" });
  }

  function renderRepos(animate = true) {
    const grid = one("repos");
    const q = state.q;
    let list = repos.filter((p) => (state.cat === "All" || p.category === state.cat) &&
      (!state.filter || state.filter.names.includes(p.name)) &&
      (!q || [p.name, p.description, p.tagline, p.language, p.category, ...p.topics, ...p.tech].join(" ").toLowerCase().includes(q)));
    const key = { updated: (p) => -Date.parse(p.last_commit || p.pushed), commits: (p) => -p.commits,
      stars: (p) => -(p.stars * 1e6 + p.commits), name: (p) => p.name.toLowerCase() }[state.sort];
    list = list.sort((a, b) => (key(a) < key(b) ? -1 : key(a) > key(b) ? 1 : 0));
    // FLIP: remember where cards were, re-order, then animate each from its old place.
    const before = new Map([...grid.children].filter((n) => n.dataset.key).map((n) => [n.dataset.key, n.getBoundingClientRect()]));
    const nodes = list.map((p) => repoNodes.get(p.name));
    grid.replaceChildren(...(nodes.length ? nodes : [el("div", { class: "empty" }, "No repositories match. Try another search or clear the filter.")]));
    document.querySelector(".result-count").textContent = plural(list.length, "repository", "repositories");
    if (!animate || reduce) return;
    for (const n of nodes) {
      const was = before.get(n.dataset.key), now = n.getBoundingClientRect();
      if (was) {
        const dx = was.left - now.left, dy = was.top - now.top;
        if (dx || dy) n.animate([{ transform: `translate(${dx}px, ${dy}px)` }, { transform: "none" }], { duration: 500, easing: "cubic-bezier(.16,1,.3,1)" });
      } else {
        n.animate([{ opacity: 0, transform: "scale(.96)" }, { opacity: 1, transform: "none" }], { duration: 380, easing: "cubic-bezier(.22,.61,.36,1)" });
      }
    }
  }

  // ── Activity ─────────────────────────────────────────────────────────────
  function bars(target, items, onClick) {
    const top = Math.max(...items.map((i) => i[1]), 1);
    one(target).replaceChildren(...items.map(([name, v, label], i) => {
      const row = el("div", { class: "bar-row", style: `--v:${(v / top).toFixed(4)};--d:${0.06 * i}s` },
        el("span", { class: "name", title: name }, name), el("span", { class: "track" }, el("span", { class: "fill" })), el("span", { class: "val" }, label));
      if (onClick) {
        row.setAttribute("role", "button"); row.tabIndex = 0; row.style.cursor = "pointer";
        row.addEventListener("click", () => onClick(name));
        row.addEventListener("keydown", (e) => { if (e.key === "Enter") onClick(name); });
      }
      return row;
    }));
  }

  function activity() {
    const a = M.activity, days = a.days || [];
    const card = one("activity");
    if (!days.length) { card.replaceChildren(el("p", {}, "No public contribution data yet.")); return; }
    const nonzero = days.map((d) => d[1]).filter(Boolean).sort((x, y) => x - y);
    const q = [0.25, 0.5, 0.75].map((f) => nonzero[Math.floor(nonzero.length * f)] || 1);
    const level = (c) => (!c ? 0 : c <= q[0] ? 1 : c <= q[1] ? 2 : c <= q[2] ? 3 : 4);
    const first = new Date(days[0][0] + "T00:00:00Z"), offset = first.getUTCDay();
    const cells = [el("span"), ...["", "Mon", "", "Wed", "", "Fri", ""].map((d) => el("span", { class: "wd" }, d))];
    const weeks = Math.ceil((days.length + offset) / 7);
    let lastMonth = -1, lastLabelCol = -9;
    for (let w = 0; w < weeks; w++) {
      const weekDays = Array.from({ length: 7 }, (_, r) => days[w * 7 + r - offset]);
      const firstDay = weekDays.find(Boolean);
      const month = firstDay ? new Date(firstDay[0] + "T00:00:00Z").getUTCMonth() : lastMonth;
      const label = month !== lastMonth && w - lastLabelCol >= 3 && w < weeks - 1;
      cells.push(el("span", { class: "m" }, label ? new Date(firstDay[0] + "T00:00:00Z").toLocaleString("en-US", { month: "short", timeZone: "UTC" }) : ""));
      if (label) lastLabelCol = w;
      lastMonth = month;
      for (const d of weekDays) {
        if (!d) { cells.push(el("span")); continue; }
        const c = el("span", { class: `c l${level(d[1])}`, style: `--d:${(w * 0.012).toFixed(3)}s` });
        attachTip(c, () => tipBody(d[1] ? plural(d[1], "contribution") : "No contributions", fmtDate(d[0])));
        cells.push(c);
      }
    }
    const heat = el("div", { class: "heat", role: "img",
      "aria-label": `${a.total} contributions between ${fmtDate(days[0][0])} and ${fmtDate(days.at(-1)[0])}` }, cells);
    const kpis = [[a.total, "Contributions"], [a.active_days, "Active days"], [a.current_streak, "Current streak", "d"],
      [a.longest_streak, "Longest streak", "d"], [a.best_day.count, a.best_day.count ? "Best day · " + fmtDate(a.best_day.date) : "Best day"]];
    card.replaceChildren(
      el("div", { class: "heat-head" }, el("div", { class: "eyebrow" }, "Contributions · last 12 months"),
        el("span", { class: "num", style: "font-size:.8125rem;color:var(--muted)" }, `${fmtDate(days[0][0])} – ${fmtDate(days.at(-1)[0])}`)),
      el("div", { class: "heat-scroll" }, heat),
      el("div", { class: "legend" }, "Less", [0, 1, 2, 3, 4].map((l) => el("i", { style: `background:var(--heat-${l})` })), "More"),
      el("div", { class: "kpis" }, kpis.map(([v, l, s]) => el("div", { class: "kpi" },
        el("div", { class: "value", "data-count": v, "data-suffix": s || "" }, "0"), el("div", { class: "label" }, l)))));
    io.observe(card);
    // Scroll the calendar to the most recent weeks on narrow screens.
    requestAnimationFrame(() => { const s = card.querySelector(".heat-scroll"); s.scrollLeft = s.scrollWidth; });

    one("timeline").replaceChildren(...M.events.map((e) => el("li", { class: e.kind === "release" ? "release" : "" },
      el("div", { class: "when" }, fmtDate(e.date)), el("div", { class: "what" }, e.title), el("div", { class: "detail" }, e.detail))));
    bars("mix", [["Commits", a.commits, String(a.commits)], ["Pull requests", a.pull_requests, String(a.pull_requests)],
      ["Issues", a.issues, String(a.issues)], ["Reviews", a.reviews, String(a.reviews)],
      ["New repositories", a.repos_created, String(a.repos_created)]]);
    bars("languages", M.languages.map((l) => [l.name, l.share, (l.share * 100).toFixed(1) + "%"]));
    bars("cats", M.categories.map((c) => [c.name, c.repos.length, String(c.repos.length)]), (name) => {
      const btn = document.querySelector(`[data-cat="${CSS.escape(name)}"]`);
      if (btn) btn.click();
      document.getElementById("explorer").scrollIntoView({ behavior: reduce ? "auto" : "smooth" });
    });
  }

  // ── Open source & connect ────────────────────────────────────────────────
  function openSource() {
    const t = M.totals, a = M.activity;
    const items = [[t.licensed, `Open-source licensed (of ${t.public_repos})`], [t.stars, "Stars earned"],
      [a.pull_requests, "Pull requests · 12 months"], [a.external_repos.length, "External repositories contributed to"]];
    one("os").replaceChildren(...items.map(([v, l], i) => el("div", { class: "card reveal", style: `--d:${0.05 * i}s` },
      el("div", { class: "value", "data-count": v }, "0"), el("div", { class: "label" }, l))));
    one("os-extra").replaceChildren(...(a.external_repos.length ? ["Contributed to",
      ...a.external_repos.map((r) => el("a", { class: "chip ghost", href: `https://github.com/${r}` }, r))] : []));
  }

  function connect(gh) {
    one("links").replaceChildren(...M.links.map((l, i) => el("a", { class: "btn" + (i === 0 ? " primary" : ""), href: l.url }, l.label)),
      el("a", { class: "btn", href: gh }, "GitHub"));
  }

  // ── Navigation: translucent bar + scrollspy pill ─────────────────────────
  function nav() {
    const bar = document.querySelector(".nav"), ind = document.querySelector(".nav-indicator");
    const links = [...document.querySelectorAll(".nav-links a")];
    const onScroll = () => bar.classList.toggle("scrolled", scrollY > 8);
    addEventListener("scroll", onScroll, { passive: true });
    onScroll();
    const move = (a) => {
      links.forEach((l) => l.classList.toggle("active", l === a));
      if (!a) { ind.style.opacity = 0; return; }
      ind.style.opacity = 1;
      ind.style.width = a.offsetWidth + "px";
      ind.style.transform = `translateX(${a.offsetLeft}px)`;
      const row = a.closest(".nav-links");
      if (row.scrollWidth > row.clientWidth) row.scrollTo({ left: a.offsetLeft - (row.clientWidth - a.offsetWidth) / 2, behavior: reduce ? "auto" : "smooth" });
    };
    const spy = new IntersectionObserver((entries) => {
      for (const e of entries) if (e.isIntersecting) move(links.find((l) => l.hash === "#" + e.target.id) || null);
    }, { rootMargin: "-45% 0px -50% 0px" });
    links.forEach((l) => { const s = document.querySelector(l.hash); if (s) spy.observe(s); });
    spy.observe(document.querySelector(".hero"));
  }
})();
